function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 100) return 'nums needs 2 to 100 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 9999)) return 'Each value is a whole number from 1 to 9999.';
  if (nums.some(v => v % 10 === 0)) return 'No value may end in the digit 0.';
  return null;
}

