function countBeautifulPairs(nums) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const firstCount = new Array(10).fill(0);
  let pairs = 0;
  for (const num of nums) {
    const last = num % 10;
    for (let digit = 1; digit <= 9; digit++) {
      if (gcd(digit, last) === 1) {
        pairs += firstCount[digit];
      }
    }
    let first = num;
    while (first >= 10) {
      first = Math.floor(first / 10);
    }
    firstCount[first]++;
  }
  return pairs;
}

