function countBeautifulPairs(nums) {
  // Check every pair directly, reading the digits from the decimal text.
  const coprime = (x, y) => {
    for (let d = 2; d <= 9; d++) if (x % d === 0 && y % d === 0) return false;
    return true;
  };
  let count = 0;
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      const lead = Number(String(nums[i])[0]);
      const unit = Number(String(nums[j]).slice(-1));
      if (coprime(lead, unit)) count++;
    }
  }
  return count;
}

