function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  // Some cases use only a few digits so that non-coprime pairs (shared factors 2, 3) are common.
  const narrow = rand() < 0.4;
  const pickDigit = from => (narrow ? [2, 3, 4, 6, 8, 9][Math.floor(rand() * 6)] : from + Math.floor(rand() * (10 - from)));
  const nums = [];
  for (let k = 0; k < n; k++) {
    const length = 1 + Math.floor(rand() * 4);
    let value = pickDigit(1);
    if (length > 1) {
      for (let t = 0; t < length - 2; t++) value = value * 10 + Math.floor(rand() * 10);
      value = value * 10 + pickDigit(1);
    }
    nums.push(value);
  }
  return [nums];
}
